class Solution {
  public int countPathsWithXorValue(int[][] grid, int k) {
    final int MOD = 1_000_000_007;
    int m = grid.length, n = grid[0].length;
    int[][] dp = new int[n][16];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        int[] cur = new int[16];
        int g = grid[i][j];
        if (i == 0 && j == 0) {
          cur[g] = 1;
        } else {
          for (int x = 0; x < 16; x++) {
            int ways = 0;
            if (i > 0) ways += dp[j][x];
            if (ways >= MOD) ways -= MOD;
            if (j > 0) ways += dp[j - 1][x];
            if (ways >= MOD) ways -= MOD;
            cur[x ^ g] = ways;
          }
        }
        dp[j] = cur;
      }
    }
    return dp[n - 1][k];
  }
}
